bool isWithinSmoothingRadius(glm::vec3 pos1, glm::vec3 pos2, float h2) {
    float dx = pos1.x - pos2.x;
    float dy = pos1.y - pos2.y;
    float dz = pos1.z - pos2.z;
    return dx*dx + dy*dy + dz*dz < h2;
}

